#!/usr/bin/env python3
"""Parse review-queue.md parts (b) and (c) into items; write items.json."""
import json, re, sys

path = sys.argv[1]
out = sys.argv[2]
lines = open(path, encoding='utf-8').read().split('\n')
items = []
part = None
theme = None
cur = None
for i, ln in enumerate(lines, 1):
    if ln.startswith('## (b)'):
        part = 'b'; continue
    if ln.startswith('## (c)'):
        part = 'c'; continue
    if ln.startswith('## (a)'):
        part = None
        if cur: items.append(cur); cur = None
        break
    if part is None:
        continue
    if ln.startswith('### '):
        if cur: items.append(cur); cur = None
        theme = ln[4:]
        continue
    m = re.match(r'^(\d+)\. ', ln)
    if m:
        if cur: items.append(cur)
        cur = {'n': int(m.group(1)), 'part': part, 'theme': theme, 'start': i, 'lines': [ln]}
        continue
    if cur is not None:
        if ln.strip() == '' :
            cur['lines'].append(ln)
        elif ln.startswith('   '):
            cur['lines'].append(ln)
        else:
            # a non-item line inside a section (preamble)
            items.append(cur); cur = None
            print('preamble line', i, ln[:100], file=sys.stderr)
if cur: items.append(cur)
for it in items:
    while it['lines'] and it['lines'][-1].strip() == '':
        it['lines'].pop()
    it['end'] = it['start'] + len(it['lines']) - 1
    txt = '\n'.join(it['lines'])
    it['text'] = txt
    m = re.match(r'^\d+\. \*\*(.+?)\*\*', it['lines'][0])
    it['title'] = m.group(1) if m else it['lines'][0].split('. ', 1)[1][:200]
    sub = {}
    for l in it['lines'][1:]:
        mm = re.match(r'^   - ([A-Z][^:]{1,20}): (.*)$', l)
        if mm:
            sub[mm.group(1)] = mm.group(2)
    it['sub'] = sub
    it['rows'] = sorted(set(int(x) for x in re.findall(r'\brows? (\d+)', txt)) |
                        set(int(x) for y in re.findall(r'\brows ((?:\d+(?:, | and | to |, and ))+\d+)', txt) for x in re.findall(r'\d+', y)))
    it['F'] = sorted(set(re.findall(r'\bF-\d+', txt)), key=lambda s: int(s[2:]))
    it['P'] = sorted(set(re.findall(r'\bP-\d+', txt)), key=lambda s: int(s[2:]))
    del it['lines']
json.dump(items, open(out, 'w'), indent=1)
print(len(items), 'items;', sum(1 for i in items if i['part']=='b'), 'in b;', sum(1 for i in items if i['part']=='c'), 'in c')
nums = [i['n'] for i in items]
print('dups', [n for n in set(nums) if nums.count(n) > 1])
print('no needed-by', [i['n'] for i in items if 'Needed by' not in i['sub']])

