#!/usr/bin/env python3
"""Enrich items.json with ledger statuses and PLAN mentions; print compact digests."""
import json, re, sys
Q = '/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/qt/'
W = '/home/user/fortress-queue-triage/explorations/coordinator/'
items = json.load(open(Q + 'items.json'))
heads = {}
for ln in open(Q + 'heads.tsv', encoding='utf-8'):
    p = ln.rstrip('\n').split('\t')
    heads[int(p[0])] = (p[1], p[3][:90])

# PLAN mentions of review-queue items
plan = open(W + 'PLAN.md', encoding='utf-8').read().split('\n')
sec = ''
sub = ''
mentions = {}
def numlist(s):
    return [int(x) for x in re.findall(r'\d+', s)]
for i, ln in enumerate(plan, 1):
    if ln.startswith('## '):
        sec = ln[3:]; sub = ''
        continue
    if ln.startswith('### '):
        sub = ln[4:]
        continue
    for m in re.finditer(r'[Rr]eview-queue items? ((?:\d+(?: \([^)]*\))?(?:, | and |, and | to )?)+)', ln):
        for n in numlist(re.sub(r'\([^)]*\)', '', m.group(1))):
            mentions.setdefault(n, []).append((i, (sub or sec)[:50]))
    for m in re.finditer(r'\bitems? ((?:\d+(?:, | and |, and )?)+)\b', ln):
        pass
for it in items:
    it['rowstat'] = [(r, heads.get(r, ('?', ''))[0]) for r in it['rows']]
    it['plan'] = sorted(set(mentions.get(it['n'], [])))
json.dump(items, open(Q + 'items2.json', 'w'), indent=1)

def short(s, n):
    s = s or ''
    return s if len(s) <= n else s[:n] + '…'
out = open(Q + 'digest.txt', 'w')
for it in items:
    out.write(f"== {it['n']} [{it['part']}] {it['theme']} (lines {it['start']}-{it['end']}, {len(it['text'])} ch)\n")
    out.write('T: ' + short(it['title'], 300) + '\n')
    out.write('L: ' + short(it['sub'].get('Landed', ''), 300) + '\n')
    out.write('N: ' + short(it['sub'].get('Needed by', ''), 300) + '\n')
    out.write('rows: ' + ' '.join(f"{r}:{s[:4]}" for r, s in it['rowstat']) + ' | F: ' + ' '.join(it['F']) + ' | P: ' + ' '.join(it['P']) + '\n')
    out.write('PLAN: ' + '; '.join(f"{l}:{s}" for l, s in it['plan']) + '\n')
print('done')

